import { apiRequest } from './api.js';
import { byId, openModal } from './dom.js';
import { escapeHTML, money } from './format.js';
import { findHome } from './store.js';
import { createPanoViewer } from './panoViewer.js';

// Self-hosted sample (generated by scripts/generate-sample-panorama.py), so the tour needs no third-party image.
const SAMPLE_PANORAMA = '/public/assets/sample-room-360.jpg';

export function showTour(id) {
  const home = findHome(id);
  if (!home) return;
  openModal(`<p class="eyebrow">IMMERSIVE ROOM EXPERIENCE · SAMPLE IMAGE</p><h2>${escapeHTML(home.name)} — 360° Tour</h2><div class="panorama" id="pano"></div><p class="muted">Drag to look around. This sample panorama is for demonstration; replace with owner-verified 360° room images before production.</p>`);
  const box = byId('pano');
  // Last-resort fallback: the same panorama as a wrap-around strip that can be dragged left/right
  // (and drifts slowly until touched). Used only if the canvas viewer cannot start.
  const fallback = reason => {
    if (!box || !box.isConnected) return;
    box.innerHTML = `<p style="position:absolute;z-index:1;margin:0;padding:8px 12px;color:#fff;font-size:12px;background:#0008">Drag left/right to look around (flat view: ${escapeHTML(reason || 'the 3D viewer is unavailable on this device')}).</p>`;
    Object.assign(box.style, { position: 'relative', overflow: 'hidden', cursor: 'grab', touchAction: 'pan-y',
      background: `#152c23 url("${SAMPLE_PANORAMA}") 0 0 / auto 100% repeat-x` });
    let offset = 0, dragging = false, lastX = 0, auto = true;
    const paint = () => { box.style.backgroundPositionX = `${offset}px`; };
    box.onpointerdown = event => { dragging = true; auto = false; lastX = event.clientX; box.setPointerCapture(event.pointerId); box.style.cursor = 'grabbing'; };
    box.onpointermove = event => { if (!dragging) return; offset += event.clientX - lastX; lastX = event.clientX; paint(); };
    box.onpointerup = box.onpointercancel = () => { dragging = false; box.style.cursor = 'grab'; };
    const drift = () => { if (!box.isConnected) return; if (auto) { offset -= 0.4; paint(); } requestAnimationFrame(drift); };
    drift();
  };
  // 1) Pannellum (WebGL) is the primary viewer. 2) If its library is blocked, WebGL is unavailable or it
  // does not finish loading, the built-in canvas viewer (public/js/panoViewer.js) takes over. 3) The flat
  // strip above is the last resort.
  const useBuiltIn = () => {
    if (!box || !box.isConnected) return;
    if (window.pano) { try { window.pano.destroy(); } catch { /* already gone */ } window.pano = null; }
    box.className = 'panorama'; box.removeAttribute('style');
    try { createPanoViewer(box, SAMPLE_PANORAMA, { onError: reason => fallback(reason) }); }
    catch (error) { fallback(error && error.message); }
  };
  if (!window.pannellum) return useBuiltIn();
  try {
    const viewer = window.pannellum.viewer('pano', { type: 'equirectangular', panorama: SAMPLE_PANORAMA, autoLoad: true, showControls: true });
    window.pano = viewer;
    const giveUp = setTimeout(() => { if (window.pano === viewer && !viewer.isLoaded()) useBuiltIn(); }, 6000);
    viewer.on('load', () => clearTimeout(giveUp));
    viewer.on('error', () => { clearTimeout(giveUp); if (window.pano === viewer) useBuiltIn(); });
  } catch { useBuiltIn(); }
}

const VERDICT_TEXT = {
  ABOVE_MARKET: 'above the city median',
  BELOW_MARKET: 'below the city median',
  FAIR: 'in line with the city median'
};

export async function showDetails(id) {
  const home = findHome(id);
  if (!home) return;
  openModal(`<p class="eyebrow">SAMPLE LISTING · DEMO LISTING</p><h2>${escapeHTML(home.name)}</h2><img src="${escapeHTML(home.image)}" alt="${escapeHTML(home.name)}" style="width:100%;max-height:330px;object-fit:cover"><p>${escapeHTML(home.description)}</p><p><b>${escapeHTML(home.area)}, ${escapeHTML(home.city)}</b> · ${home.bhk} BHK · ${home.size} sq.ft.</p><p>Monthly rent: <b>${money(home.rent)}</b> · Deposit: <b>${money(home.deposit)}</b> · Maintenance: <b>${money(home.maintenance)}</b></p><p>${escapeHTML(home.furnishing)} · Pets: ${home.pets ? 'Allowed' : 'Not listed'} · Parking: ${home.parking ? 'Available' : 'Unavailable'}</p><p id="priceInsight" class="muted">Checking price insight…</p><button class="btn dark" data-scroll-visit>Request a visit →</button>`);
  try {
    const insight = await apiRequest(`/api/properties/${id}/insight`);
    const target = byId('priceInsight');
    if (target) {
      target.textContent = `Price insight: ₹${insight.rentPerSqft}/sq.ft. is ${VERDICT_TEXT[insight.verdict]} (₹${insight.cityMedianPerSqft}/sq.ft., ${insight.differencePercent >= 0 ? '+' : ''}${insight.differencePercent}%). ${insight.note}`;
    }
  } catch {
    const target = byId('priceInsight');
    if (target) target.textContent = 'Price insight is unavailable right now.';
  }
}
